/* ---- 2. Songbook PDF builder ---- */
/* ============================================================
   UCN SONGBOOK — PDF BUILDER
   Constructs the full songbook PDF using jsPDF by placing text
   and shapes at explicit coordinates (no window.print(), no
   html2canvas). Written as a standalone function so it can be
   loaded identically in the browser (embedded jsPDF) and in a
   Node test harness (npm/local jsPDF) for automated verification.

   Usage:
     buildSongbookPDF(jsPDFCtor, songs, assets) -> jsPDF doc instance
     assets = { logoBase64, qrBase64, fonts: {exoRegular, exoBold, orbitronBold} }
   ============================================================ */
(function(root, factory){
  if (typeof module === 'object' && module.exports) {
    module.exports = factory();
  } else {
    root.buildSongbookPDF = factory();
  }
})(typeof self !== 'undefined' ? self : this, function(){

  // ---- Layout constants (points, A4 = 595.28 x 841.89) ----
  var PAGE_W = 595.28, PAGE_H = 841.89;
  var MARGIN = 56;                 // content margin from page edge
  var FRAME_INSET = 24;            // corner-frame border inset from page edge
  var CONTENT_W = PAGE_W - MARGIN * 2;
  var CONTENT_TOP = MARGIN;
  var CONTENT_BOTTOM = PAGE_H - MARGIN - 18; // leave room for footer

  // ---- Palette (matches the app's UCN theme, adapted for print/white bg) ----
  var COLOR = {
    navy:      [27, 42, 94],
    accent:    [51, 122, 150],   // slightly darkened cyan for print contrast on white
    orange:    [180, 92, 24],    // slightly darkened orange for print contrast
    text:      [30, 38, 54],
    muted:     [100, 108, 122],
    faint:     [150, 158, 170],
    border:    [205, 210, 220],
    choruseBg: [253, 240, 227]   // light warm tint behind chorus blocks
  };

  var CATEGORY_ORDER = [
    'Patriotic Songs','Bar/Drinking Songs','Crew Ballads','Accompanied Songs',
    'Songs About Us','Fragments and Works in Progress','Traditional Songs',
    'Movie/TV','Improvised Songs','Folk & Other'
  ];

  function buildSongbookPDF(jsPDFCtor, songs, assets){
    songs = songs || [];
    assets = assets || {};

    var doc = new jsPDFCtor({ unit: 'pt', format: 'a4', compress: true });

    // ---- Font registration, with silent fallback to Helvetica ----
    // NOTE: jsPDF can internally swallow certain font-registration errors
    // via its own pub/sub error system without throwing where a normal
    // try/catch would see it — so registration success is verified by
    // actually checking doc.getFontList() afterwards, not just by the
    // absence of a thrown exception.
    var fontsOK = false;
    try {
      if (assets.fonts && assets.fonts.exoRegular) {
        doc.addFileToVFS('Exo2-Regular.ttf', assets.fonts.exoRegular);
        doc.addFont('Exo2-Regular.ttf', 'Exo2', 'normal');
        doc.addFileToVFS('Exo2-Bold.ttf', assets.fonts.exoBold);
        doc.addFont('Exo2-Bold.ttf', 'Exo2', 'bold');
        doc.addFileToVFS('Orbitron-Bold.ttf', assets.fonts.orbitronBold);
        doc.addFont('Orbitron-Bold.ttf', 'Orbitron', 'bold');

        var registered = doc.getFontList();
        var exoOK = registered['Exo2'] && registered['Exo2'].indexOf('normal') > -1 && registered['Exo2'].indexOf('bold') > -1;
        var orbitronOK = registered['Orbitron'] && registered['Orbitron'].indexOf('bold') > -1;

        if (exoOK && orbitronOK) {
          // jsPDF registers a font's NAME optimistically at addFont() time, but only
          // actually parses the underlying font-file bytes lazily, the first time
          // that font is used to measure/draw text. A broken font can therefore
          // "succeed" at registration and still crash later, unprotected, the first
          // time real content tries to use it. Forcing that lazy parse to happen
          // right here — still inside this try/catch — catches it safely instead.
          doc.setFont('Exo2', 'normal'); doc.getTextWidth('Test');
          doc.setFont('Exo2', 'bold');   doc.getTextWidth('Test');
          doc.setFont('Orbitron', 'bold'); doc.getTextWidth('Test');
          doc.setFont('helvetica', 'normal'); // reset to a safe default before real content begins
          fontsOK = true;
        }
      }
    } catch (e) { fontsOK = false; }

    function bodyFont(weight){ return fontsOK ? ['Exo2', weight || 'normal'] : ['helvetica', weight || 'normal']; }
    function headFont(){ return fontsOK ? ['Orbitron', 'bold'] : ['helvetica', 'bold']; }
    function setBody(size, weight, color){
      var f = bodyFont(weight);
      doc.setFont(f[0], f[1]);
      doc.setFontSize(size);
      doc.setTextColor.apply(doc, color || COLOR.text);
    }
    function setHead(size, color){
      var f = headFont();
      doc.setFont(f[0], f[1]);
      doc.setFontSize(size);
      doc.setTextColor.apply(doc, color || COLOR.navy);
    }

    // ---- Corner frame: thin border + accent corner marks, drawn on EVERY page ----
    function drawFrame(){
      var x0 = FRAME_INSET, y0 = FRAME_INSET;
      var x1 = PAGE_W - FRAME_INSET, y1 = PAGE_H - FRAME_INSET;
      doc.setDrawColor.apply(doc, COLOR.border);
      doc.setLineWidth(0.6);
      doc.rect(x0, y0, x1 - x0, y1 - y0);

      var legLen = 16;
      doc.setDrawColor.apply(doc, COLOR.accent);
      doc.setLineWidth(1.4);
      // top-left
      doc.line(x0, y0 + legLen, x0, y0); doc.line(x0, y0, x0 + legLen, y0);
      // top-right
      doc.line(x1 - legLen, y0, x1, y0); doc.line(x1, y0, x1, y0 + legLen);
      // bottom-left
      doc.line(x0, y1 - legLen, x0, y1); doc.line(x0, y1, x0 + legLen, y1);
      // bottom-right
      doc.line(x1 - legLen, y1, x1, y1); doc.line(x1, y1, x1, y1 - legLen);
    }

    function newPage(){
      doc.addPage();
      drawFrame();
      return CONTENT_TOP;
    }

    // Draw frame on the first page (created implicitly by `new jsPDF()`, so no addPage() event fires for it)
    drawFrame();

    // ============================================================
    // PAGE 1 — COVER
    // ============================================================
    (function drawCover(){
      var cx = PAGE_W / 2;
      var y = 150;

      if (assets.logoBase64) {
        var logoW = 130, logoH = 130;
        try {
          doc.addImage(assets.logoBase64, 'PNG', cx - logoW / 2, y, logoW, logoH);
        } catch (e) { /* image failed to decode — continue without it */ }
        y += logoH + 34;
      } else {
        y += 20;
      }

      doc.setDrawColor.apply(doc, COLOR.navy);
      doc.setLineWidth(1);
      doc.line(cx - 140, y, cx + 140, y);
      y += 34;

      setHead(34, COLOR.navy);
      doc.text('UCN SONGBOOK', cx, y, { align: 'center' });
      y += 22;

      setBody(11, 'normal', COLOR.muted);
      doc.text('The Unofficially Official Songbook of the UCN Officer Corps', cx, y, { align: 'center' });
      y += 26;

      doc.setDrawColor.apply(doc, COLOR.navy);
      doc.line(cx - 140, y, cx + 140, y);
      y += 40;

      if (assets.qrBase64) {
        var qrSize = 130;
        try {
          doc.addImage(assets.qrBase64, 'PNG', cx - qrSize / 2, y, qrSize, qrSize);
        } catch (e) { /* image failed to decode — continue without it */ }
        y += qrSize + 14;
        setBody(9, 'normal', COLOR.muted);
        doc.text('Scan for the digital songbook', cx, y, { align: 'center' });
        y += 13;
        setBody(9, 'bold', COLOR.accent);
        doc.text('shantysongbook.netlify.app', cx, y, { align: 'center' });
      }

      setBody(9, 'normal', COLOR.faint);
      doc.text(String(songs.length) + ' songs', cx, PAGE_H - FRAME_INSET - 34, { align: 'center' });
    })();

    // ============================================================
    // PAGE 2 — TABLE OF CONTENTS (placeholder; filled in at the end
    // once every section's real starting page number is known)
    // ============================================================
    newPage();
    var TOC_PAGE = doc.internal.getNumberOfPages();

    var tocEntries = [];

    // ============================================================
    // PAGE 3 — CREDITS & DISCLAIMER
    // ============================================================
    (function drawCredits(){
      var y = newPage();
      tocEntries.push({ title: 'Credits & Disclaimer', page: doc.internal.getNumberOfPages() });

      y = drawSectionHeading('Credits & Disclaimer', y);

      function block(label, body){
        setBody(9, 'bold', COLOR.muted);
        doc.text(label.toUpperCase(), MARGIN, y);
        y += 14;
        setBody(11, 'normal', COLOR.text);
        var lines = doc.splitTextToSize(body, CONTENT_W);
        doc.text(lines, MARGIN, y);
        y += lines.length * 14 + 18;
      }

      block('Made by', "Sub Lt Tetra \u2014 Discord: finlay3110");
      block('Original Songbook', "Compiled by Lt. Cmdr. Jim \u2014 Ship's Councillor");
      block('Traditional Songs', "Traditional Songs booklet by Lt. Dorward");
      block('Requesting Updates', "Post in the #songbook channel on the BC Discord server, or DM Tetra directly.");

      y += 6;
      doc.setDrawColor.apply(doc, COLOR.border);
      doc.setLineWidth(0.6);
      doc.line(MARGIN, y, PAGE_W - MARGIN, y);
      y += 24;

      setBody(9, 'bold', COLOR.muted);
      doc.text('DISCLAIMER', MARGIN, y);
      y += 16;
      setBody(9.5, 'normal', COLOR.muted);
      var disclaimerLines = [
        'The UCN logo is the property of Bridge Command / The London Space Elevator Limited.',
        'This is a fan-made project and is not approved by or affiliated with Bridge Command / The London Space Elevator Limited.',
        'Song lyrics are the property of their respective copyright holders. UCN-themed songs are reproduced here as original fan parodies.'
      ];
      disclaimerLines.forEach(function(line){
        var wrapped = doc.splitTextToSize(line, CONTENT_W);
        doc.text(wrapped, MARGIN, y);
        y += wrapped.length * 13 + 8;
      });
    })();

    // ---- Shared: draw an uppercase section heading with underline rule ----
    function drawSectionHeading(title, y){
      setHead(20, COLOR.navy);
      doc.text(title.toUpperCase(), MARGIN, y);
      y += 8;
      doc.setDrawColor.apply(doc, COLOR.accent);
      doc.setLineWidth(2);
      doc.line(MARGIN, y, MARGIN + 90, y);
      return y + 28;
    }

    // ---- Ensure enough vertical room remains; otherwise start a new (plain) page ----
    function ensureRoom(y, needed){
      if (y + needed > CONTENT_BOTTOM) {
        return newPage();
      }
      return y;
    }

    // ---- Render one song's lyrics using the same parsing rules as the app ----
    function drawLyrics(song, y){
      var blocks = song.lyrics.split('\n\n');
      var chorusLines = null;

      for (var bi = 0; bi < blocks.length; bi++) {
        var block = blocks[bi];
        var lines = block.split('\n');
        var first = (lines[0] || '').trim();
        if (!first) continue;

        // [Section Label]
        if (/^\[.+\]$/.test(first) && lines.length <= 2) {
          y = ensureRoom(y, 16);
          setBody(9, 'bold', COLOR.accent);
          doc.text(first.slice(1, -1).toUpperCase(), MARGIN, y);
          y += 16;
          continue;
        }

        // Repeat marker
        if (/^repeat /i.test(first) && lines.length <= 2) {
          y = ensureRoom(y, 16);
          setBody(9, 'normal', COLOR.faint);
          doc.text('\u21BA ' + block.trim(), PAGE_W / 2, y, { align: 'center', fontStyle: 'italic' });
          y += 18;
          continue;
        }

        // Chorus block
        if (/^(chorus[\s\d]*:?|\[chorus[\s\d]*\])/i.test(first)) {
          var content = lines.slice(1);
          if (!chorusLines) chorusLines = content;
          y = drawChorusBox(content, y);
          continue;
        }

        // Regular verse
        for (var li = 0; li < lines.length; li++) {
          y = ensureRoom(y, 14);
          setBody(10.5, 'normal', COLOR.text);
          doc.text(lines[li] || ' ', MARGIN, y);
          y += 14;
        }
        y += 8;
      }
      return y;
    }

    function drawChorusBox(lines, y){
      var padX = 12, padY = 8, lineH = 14;
      var boxH = padY * 2 + lines.length * lineH;
      y = ensureRoom(y, boxH + 10);

      doc.setFillColor.apply(doc, COLOR.choruseBg);
      doc.setDrawColor.apply(doc, COLOR.orange);
      doc.setLineWidth(0);
      doc.roundedRect(MARGIN, y, CONTENT_W, boxH, 3, 3, 'F');
      // left accent bar
      doc.setFillColor.apply(doc, COLOR.orange);
      doc.rect(MARGIN, y, 3, boxH, 'F');

      var ty = y + padY + 9;
      setBody(10.5, 'normal', COLOR.text);
      for (var i = 0; i < lines.length; i++) {
        doc.text(lines[i] || ' ', MARGIN + padX + 4, ty);
        ty += lineH;
      }
      return y + boxH + 12;
    }

    // ============================================================
    // SECTION PAGES — one per category, songs flow with page breaks
    // ============================================================
    var presentCategories = [];
    songs.forEach(function(s){
      if (presentCategories.indexOf(s.category) === -1) presentCategories.push(s.category);
    });
    // Prefer the canonical order; append any unexpected/future categories at the end
    var orderedCategories = CATEGORY_ORDER.filter(function(c){ return presentCategories.indexOf(c) > -1; });
    presentCategories.forEach(function(c){ if (orderedCategories.indexOf(c) === -1) orderedCategories.push(c); });

    orderedCategories.forEach(function(category){
      var y = newPage();
      tocEntries.push({ title: category, page: doc.internal.getNumberOfPages() });
      y = drawSectionHeading(category, y);

      var catSongs = songs.filter(function(s){ return s.category === category; });

      catSongs.forEach(function(song, idx){
        if (idx > 0) {
          y = newPage(); // every song after the section's first gets its own fresh page
        } else {
          y = ensureRoom(y, 60); // first song shares the section-heading page if room allows
        }

        setBody(13, 'bold', COLOR.navy);
        doc.text(song.title, MARGIN, y);
        y += 16;

        setBody(9, 'normal', COLOR.muted);
        if (song.tune) { doc.text('\u266A ' + song.tune, MARGIN, y); y += 12; }
        if (song.words) { doc.text('\u270D ' + song.words, MARGIN, y); y += 12; }
        if (song.source_book) { doc.text('\uD83D\uDCD6 ' + song.source_book + ', p.' + song.source_page, MARGIN, y); y += 12; }
        y += 10;

        y = drawLyrics(song, y);
        y += 14; // gap before next song (only relevant if a future layout ever shares pages again)
      });
    });

    // ============================================================
    // FOOTER — "Page X of Y" on every page except the cover
    // ============================================================
    var totalPages = doc.internal.getNumberOfPages();
    for (var p = 2; p <= totalPages; p++) {
      doc.setPage(p);
      setBody(8.5, 'normal', COLOR.faint);
      doc.text('Page ' + p + ' of ' + totalPages, PAGE_W / 2, PAGE_H - FRAME_INSET - 10, { align: 'center' });
    }

    // ============================================================
    // GO BACK AND FILL IN THE TABLE OF CONTENTS
    // (page numbers were only known once every section was built)
    // ============================================================
    doc.setPage(TOC_PAGE);
    var ty = drawSectionHeading('Table of Contents', CONTENT_TOP);

    tocEntries.forEach(function(entry){
      ty = ensureRoomTOC(ty, 22);

      setBody(11, 'normal', COLOR.text);
      doc.text(entry.title, MARGIN, ty);

      var titleW = doc.getTextWidth(entry.title);
      var pageStr = String(entry.page);
      setBody(11, 'bold', COLOR.navy);
      var pageStrW = doc.getTextWidth(pageStr);
      doc.text(pageStr, PAGE_W - MARGIN, ty, { align: 'right' });

      // Dotted leader line between the title and the page number
      var leaderX0 = MARGIN + titleW + 6;
      var leaderX1 = PAGE_W - MARGIN - pageStrW - 6;
      if (leaderX1 > leaderX0) {
        doc.setDrawColor.apply(doc, COLOR.border);
        doc.setLineWidth(0.7);
        doc.setLineDashPattern([1, 2.5], 0);
        doc.line(leaderX0, ty - 3, leaderX1, ty - 3);
        doc.setLineDashPattern([], 0);
      }

      // Real clickable link over the whole row -> jumps to that section's page
      doc.link(MARGIN, ty - 12, CONTENT_W, 18, { pageNumber: entry.page });

      ty += 22;
    });

    function ensureRoomTOC(y, needed){
      // NOTE: with ~10-11 sections this always fits on one page; if the
      // songbook grows enough categories to overflow this page, a second
      // TOC page would need inserting BEFORE section pages are built
      // (inserting one now would shift every recorded page number).
      if (y + needed > CONTENT_BOTTOM) { return CONTENT_BOTTOM; }
      return y;
    }

    doc.setPage(totalPages); // leave the doc "pointing" at the last page
    return doc;
  }

  return buildSongbookPDF;
});


/* ============================================================
   UCN SONGBOOK — PDF EXPORT ENTRY POINT
   This is the function the main app calls after this file has
   been lazily loaded. It assembles the embedded assets and hands
   everything to buildSongbookPDF() (defined above), then triggers
   the browser download.
   ============================================================ */
window.UCN_generateSongbookPDF = function(songs){
  var assets = {
    logoBase64: 'data:image/png;base64,',
    qrBase64: 'data:image/png;base64,',
    fonts: {
      exoRegular: '',
      exoBold: '',
      orbitronBold: ''
    }
  };
  var doc = window.buildSongbookPDF(window.jspdf.jsPDF, songs, assets);
  doc.save('UCN_Songbook.pdf');
};
